/* ==UserStyle==
@name           Hashtags & Links RGB
@namespace      majestic
@version        1.0.0
@author         @Majestic
@description    RGB animation only for hashtags and links.
==/UserStyle== */

@keyframes rgbText {
    0%   { color: #ff0000; }
    16%  { color: #ff00ff; }
    33%  { color: #0000ff; }
    50%  { color: #00ffff; }
    66%  { color: #00ff00; }
    83%  { color: #ffff00; }
    100% { color: #ff0000; }
}

/* Linki */
a {
    animation: rgbText 5s linear infinite !important;
}

/* Hashtagi */
[href^="#"],
[class*="hashtag"],
[class*="HashTag"] {
    animation: rgbText 5s linear infinite !important;
}
